skins.css:
/* BLOCK - lifted straight out of block/index.html, which was never wearing a
   theme at all: it loads day.js and records.js and nothing else, and every
   colour in it is its own.

   Its structure was already right. Fifteen variables, borders doing all the
   separating, almost no shadow anywhere, six-pixel corners, and two fonts - a
   squared one for labels and a plain one for reading. That is a theme, it was
   just written inside one app where nothing else could reach it.

   Measured rather than eyeballed: 6px is the corner in 37 places, borders are
   1px #1e2a38, and exactly three elements in the whole app carry a shadow. */

body { letter-spacing: var(--track-body) }

/* Flat depth removes the shadow, so the edge has to come from a line. That is
   how BLOCK does it too: a hairline round everything and no lift at all. */
.card, .mb-sheet, .mb-menu, .mb-toast {
  background: var(--surface-1);
  border: var(--border-width) solid var(--border);
}
header {
  background: var(--surface-1);
  border-bottom: var(--border-width) solid var(--border);
}
header .logo { font-family: var(--font-display); letter-spacing: var(--track-cap) }

h2 {
  font-family: var(--font-display);
  color: var(--text-muted);
  letter-spacing: var(--track-cap);
}

.item, .mb-input, .mb-sel {
  background: var(--surface-2);
  border: var(--border-width) solid var(--border);
}
.item .nm { font-family: var(--font-body) }

.chk { border-color: var(--border-strong) }
.chk.on { background: var(--accent); border-color: var(--accent); color: var(--accent-fg) }

.stat { background: var(--surface-2); border: var(--border-width) solid var(--border) }
.stat b { font-family: var(--font-display) }

button.mb-btn, .mb-act, .mb-chip, .mb-x, .mb-opt {
  font-family: var(--font-display);
  letter-spacing: var(--track-cap);
  background: var(--surface-2);
  border: var(--border-width) solid var(--border);
  color: var(--text-2);
}
button.mb-btn:hover, .mb-chip:hover { border-color: var(--border-strong); color: var(--text-1) }
.mb-btn.go { border-color: var(--accent); color: var(--accent); background: var(--surface-2) }
#fab { background: var(--accent); color: var(--accent-fg) }

/* RAGNAROK - the 2002 client.

   WHITE ON WHITE. The window, the rows, the slots and the buttons are all
   white, separated by thin blue-grey hairlines rather than by tinted bands.
   That is what makes the client look like a spreadsheet someone made pretty
   rather than a game menu.

   THE BLUE GRADIENT IS ONLY AT THE TOP. One strip, across the title bar, and
   nowhere else. Blue appears again only on numbers, on the marker beside the
   live row, and on a selected button.

   THE FONT is small bold Arial. Not a bitmap face: the client renders normal
   type small and heavy, which is why it stays crisp and readable at eleven
   pixels. Arimo matches Arial's metrics and falls back to Arial itself, so
   this theme's type is right even with no network. */

body { letter-spacing: var(--track-body) }

/* ---- the one piece of blue ---- */
header {
  background: linear-gradient(180deg, #7FA6CE 0%, #4E7FB4 48%, #3C6DA4 100%);
  color: var(--surface-1);
  border-bottom: var(--border-width) solid var(--accent);
}
header .logo {
  font-family: var(--font-display);
  font-weight: var(--w-bold);
  font-size: var(--f-3);
  color: var(--surface-1);
  letter-spacing: var(--track-cap);
}
header .logo b { color: #CFE2F5 }
header .mb-btn {
  background: var(--surface-1); color: var(--text-1);
  border: var(--border-width) solid var(--accent);
}

/* ---- everything below is white ---- */
.card, .mb-sheet, .mb-menu, .mb-toast {
  background: var(--surface-1);
  border: var(--border-width) solid var(--border);
  box-shadow: none;
}
.mb-sheet-head {
  background: linear-gradient(180deg, #7FA6CE, #3C6DA4);
  color: var(--surface-1);
  font-family: var(--font-display); font-weight: var(--w-bold);
  border-bottom: var(--border-width) solid var(--accent);
}
.mb-sheet-head .mb-grab { background: rgba(255,255,255,.7) }

/* A section heading is dark text on white over a hairline. No band, no fill. */
h2 {
  background: none;
  border: 0;
  border-bottom: var(--border-width) solid var(--border);
  box-shadow: none;
  font-family: var(--font-display);
  font-weight: var(--w-bold);
  color: var(--accent);
  padding-bottom: var(--s-2);
}

/* A row is white with a hairline, and the only mark on it is the blue arrow. */
.item {
  background: var(--surface-1);
  border: var(--border-width) solid var(--border);
  box-shadow: none;
}
.item .nm { font-family: var(--font-body); color: var(--text-1) }
.item.on .nm { color: var(--text-muted) }
.item::before {
  content: ''; width: 0; height: 0; flex: 0 0 auto; margin-right: -4px;
  border-left: 6px solid transparent;
  border-top: 4px solid transparent; border-bottom: 4px solid transparent;
}
.item.on::before { border-left-color: var(--accent) }

.mb-input, .mb-sel, .mb-range {
  background: var(--surface-1); color: var(--text-1);
  border: var(--border-width) solid var(--border);
  box-shadow: none; font-family: var(--font-body);
}

/* Buttons: white, hairline, and they invert to blue when they are on. */
button.mb-btn, .mb-act, button.chk, .mb-chip, .mb-x, .mb-opt, #fab {
  font-family: var(--font-display);
  font-weight: var(--w-bold);
  letter-spacing: var(--track-cap);
  background: var(--surface-1);
  color: var(--text-1);
  border: var(--border-width) solid var(--border-strong);
  border-radius: 0;
  box-shadow: none;
  transition: none;
}
button.mb-btn:active, .mb-act:active, button.chk:active,
.mb-chip:active, .mb-x:active, #fab:active {
  background: var(--accent); color: var(--surface-1);
}
button.chk.on { background: var(--accent); color: var(--surface-1); border-color: var(--accent) }

/* The numbers are bold and blue on white, exactly as the stat panel is. */
.stat {
  background: var(--surface-1);
  border: var(--border-width) solid var(--border);
  box-shadow: none;
}
.stat b { font-family: var(--font-display); font-weight: var(--w-bold);
  color: var(--accent) }
.stat span { font-family: var(--font-body); color: var(--text-muted) }

#fab { color: var(--accent); font-size: var(--f-5); border-color: var(--accent) }
.mb-opt:hover, .mb-chip.on { background: var(--accent); color: var(--surface-1) }

/* SYSTEM - a levelling-up status window. Light comes OFF the surfaces instead
   of falling onto them, every frame is a hairline, and the corners are cut
   with brackets rather than rounded. */

body { letter-spacing: var(--track-body) }

header {
  background: transparent;
  border-bottom: var(--border-width) solid var(--border);
  box-shadow: 0 1px 0 rgba(127,227,255,.10);
}
header .logo {
  font-family: var(--font-display);
  color: var(--text-1);
  text-shadow: 0 0 14px var(--accent);
}
header .logo b { color: var(--accent); text-shadow: 0 0 18px var(--accent) }

/* A panel is a pane of lit glass, not a solid card. */
.card, .mb-sheet, .mb-menu, .mb-toast {
  position: relative;
  background: linear-gradient(180deg, rgba(127,227,255,.05), rgba(127,227,255,.012));
  border: var(--border-width) solid var(--border);
  box-shadow: var(--e-1);
}
/* Bracket corners. Two pseudo-elements on opposite corners, no new markup. */
.card::before, .card::after {
  content: ''; position: absolute; width: 15px; height: 15px;
  border: 2px solid var(--accent); pointer-events: none;
}
.card::before { top: -1px; left: -1px; border-right: 0; border-bottom: 0 }
.card::after { bottom: -1px; right: -1px; border-left: 0; border-top: 0 }

h2 {
  font-family: var(--font-display);
  color: var(--accent);
  text-shadow: 0 0 12px var(--accent);
  border-bottom: var(--border-width) solid var(--border);
  padding-bottom: var(--s-2);
}

/* A row is a ruled line in a readout, not a filled pill. */
.item { background: transparent; border-bottom: var(--border-width) solid var(--border) }
.item.on .nm { color: var(--text-muted) }

.chk { border-radius: 2px; border-color: var(--border-strong) }
.chk.on { box-shadow: var(--e-2); border-color: var(--accent) }

/* The numbers are the whole point of a status window, so they glow. */
.stat { background: transparent; border: var(--border-width) solid var(--border) }
.stat b { color: var(--text-1); text-shadow: 0 0 16px var(--accent) }

button.mb-btn, .mb-act, .mb-chip, .mb-x, .mb-opt {
  font-family: var(--font-display);
  letter-spacing: var(--track-cap);
  background: transparent;
  color: var(--accent);
  border: var(--border-width) solid var(--border-strong);
}
button.mb-btn:active, .mb-act:active { background: var(--accent); color: var(--accent-fg) }
.mb-btn.go { background: var(--accent); color: var(--accent-fg); box-shadow: var(--e-2) }

.mb-input, .mb-sel { background: rgba(127,227,255,.05); border-color: var(--border) }
#fab { box-shadow: var(--e-3); border: var(--border-width) solid var(--accent) }

/* MONARCH - black and gold. Nothing floats and almost nothing is filled: the
   whole design is hairlines, capitals and empty space. */

body { letter-spacing: var(--track-body) }

header { background: var(--bg); border-bottom: var(--border-width) solid var(--accent) }
header .logo { font-family: var(--font-display); color: var(--accent) }
header .logo b { color: var(--text-2) }

/* A card is a ruled box with a second line just inside it. */
.card, .mb-sheet, .mb-menu, .mb-toast {
  background: var(--bg);
  border: var(--border-width) solid var(--accent);
  box-shadow: inset 0 0 0 3px var(--bg), inset 0 0 0 4px var(--border);
}

h2 {
  font-family: var(--font-display);
  color: var(--accent);
  border-bottom: var(--border-width) solid var(--border);
  padding-bottom: var(--s-2);
}

.item { background: transparent; border-bottom: var(--border-width) solid var(--border) }
.item.on .nm { color: var(--text-muted) }

.chk { border-radius: 0; border-color: var(--accent) }
.chk.on { background: var(--accent); color: var(--accent-fg) }

.stat { background: transparent; border: var(--border-width) solid var(--border) }
.stat b { font-family: var(--font-display); color: var(--accent) }

button.mb-btn, .mb-act, .mb-chip, .mb-x, .mb-opt {
  font-family: var(--font-display);
  letter-spacing: var(--track-cap);
  background: transparent;
  color: var(--accent);
  border: var(--border-width) solid var(--accent);
  border-radius: 0;
}
button.mb-btn:active, .mb-act:active, .mb-chip:active,
.mb-btn.go { background: var(--accent); color: var(--accent-fg) }

.mb-input, .mb-sel { background: transparent; border-color: var(--border);
  border-radius: 0; color: var(--text-1) }
#fab { border-radius: 0; background: var(--accent); color: var(--accent-fg);
  font-family: var(--font-display) }

/* ORNATE - a grey plate in a gold frame, with a diamond on every rule. The
   flourishes are pseudo-elements on things that already exist, so no app grows
   a single new element. */

body { letter-spacing: var(--track-body) }

header { background: var(--surface-1); border-bottom: var(--border-width) solid var(--accent) }
header .logo { font-family: var(--font-display); color: var(--accent) }
header .logo b { color: var(--text-1) }

.card, .mb-sheet, .mb-menu, .mb-toast {
  position: relative;
  background: var(--surface-1);
  border: var(--border-width) solid var(--accent);
  box-shadow: inset 0 0 0 4px var(--surface-1), inset 0 0 0 5px var(--border);
}
/* Gold corner flourishes on opposite corners, drawn rather than fetched. */
.card::before, .card::after {
  content: ''; position: absolute; width: 16px; height: 16px;
  border: 2px solid var(--accent); pointer-events: none;
}
.card::before { top: 5px; left: 5px; border-right: 0; border-bottom: 0 }
.card::after { bottom: 5px; right: 5px; border-left: 0; border-top: 0 }

/* A heading is centred and ruled, and the rule is broken by a diamond. */
h2 {
  position: relative;
  font-family: var(--font-display);
  text-align: center;
  color: var(--accent);
  border-bottom: var(--border-width) solid var(--border);
  padding-bottom: var(--s-2);
}
h2::after {
  content: '\25C6';
  position: absolute; left: 50%; bottom: -7px; transform: translateX(-50%);
  background: var(--surface-1);
  color: var(--accent); font-size: 10px; line-height: 1;
}

.item { background: transparent; border-bottom: var(--border-width) solid var(--border) }
.item.on .nm { color: var(--text-muted) }

.chk { border-radius: 0; border-color: var(--accent) }
.chk.on { background: var(--accent); color: var(--accent-fg) }

.stat { background: transparent; border: var(--border-width) solid var(--border) }
.stat b { font-family: var(--font-display); color: var(--accent) }

button.mb-btn, .mb-act, .mb-chip, .mb-x, .mb-opt {
  font-family: var(--font-display);
  letter-spacing: var(--track-cap);
  background: transparent;
  color: var(--accent);
  border: var(--border-width) solid var(--accent);
  border-radius: 0;
}
button.mb-btn:active, .mb-act:active, .mb-btn.go {
  background: var(--accent); color: var(--accent-fg);
}
.mb-input, .mb-sel { background: var(--surface-2); border-color: var(--border); border-radius: 0 }
#fab { border-radius: 0; background: var(--accent); color: var(--accent-fg);
  border: 2px solid var(--border-strong); font-family: var(--font-display) }

/* DECK - a presentation slide. A deep blue gradient, hairline rules, generous
   capitals, and rows that band the way a table on a slide does. */

body { letter-spacing: var(--track-body) }

header { background: transparent; border-bottom: var(--border-width) solid var(--border) }
header .logo { font-family: var(--font-display); color: var(--text-1) }
header .logo b { color: var(--accent) }

.card, .mb-sheet, .mb-menu, .mb-toast {
  background: rgba(255,255,255,.055);
  border: var(--border-width) solid var(--border);
}

h2 {
  font-family: var(--font-display);
  color: var(--text-1);
  border-bottom: var(--border-width) solid var(--border);
  padding-bottom: var(--s-2);
}

/* Banded rows. It has to work whether or not the row is wrapped for the swipe
   gesture, so both shapes are named. */
.item, .list > *:nth-child(odd) .item { background: rgba(255,255,255,.05) }
.list > *:nth-child(even) .item, .item:nth-child(even) { background: rgba(255,255,255,.10) }
.item.on .nm { color: var(--text-muted) }

.chk { border-color: var(--border-strong) }
.chk.on { background: var(--accent); color: var(--accent-fg); border-color: var(--accent) }

.stat { background: rgba(255,255,255,.07); border: var(--border-width) solid var(--border) }
.stat b { font-family: var(--font-display); color: var(--text-1) }

button.mb-btn, .mb-act, .mb-chip, .mb-x, .mb-opt {
  font-family: var(--font-display);
  letter-spacing: var(--track-cap);
  background: transparent;
  color: var(--text-1);
  border: var(--border-width) solid var(--border-strong);
}
button.mb-btn:active, .mb-act:active { background: rgba(255,255,255,.16) }
.mb-btn.go { background: var(--accent); color: var(--accent-fg); border-color: var(--accent) }

.mb-input, .mb-sel { background: rgba(255,255,255,.09); border-color: var(--border);
  color: var(--text-1) }
#fab { background: var(--accent); color: var(--accent-fg) }

/* SLAB - everything is a solid rectangle of colour. No rounding, no shadow,
   no gradient: separation comes from the blocks butting up against each other,
   the way a tiled interface does. */
body { letter-spacing: var(--track-body) }

header { background: var(--accent); color: var(--accent-fg) }
header .logo { font-family: var(--font-display); color: var(--accent-fg) }
header .logo b { color: var(--accent-fg); opacity: .6 }
header .mb-btn { background: rgba(0,0,0,.22); color: var(--accent-fg); border: 0 }

.card, .mb-sheet, .mb-menu, .mb-toast {
  background: var(--surface-1); border: 0; border-left: 6px solid var(--accent);
}
h2 { font-family: var(--font-display); color: var(--text-1) }

/* Rows are stacked blocks with a hairline of page showing between them. */
.item { background: var(--surface-2); border: 0 }
.item.on { background: var(--surface-3) }
.chk { border-radius: 0; border-width: 3px }
.chk.on { background: var(--accent); border-color: var(--accent); color: var(--accent-fg) }

.stat { background: var(--surface-2); border: 0 }
.stat b { font-family: var(--font-display) }
.bars i { border-radius: 0 }

button.mb-btn, .mb-act, .mb-chip, .mb-x, .mb-opt {
  font-family: var(--font-display); letter-spacing: var(--track-cap);
  background: var(--surface-3); color: var(--text-1); border: 0; border-radius: 0;
}
.mb-btn.go { background: var(--accent); color: var(--accent-fg) }
.mb-input, .mb-sel { background: var(--surface-2); border: 0; border-radius: 0;
  border-bottom: 3px solid var(--accent) }
#fab { border-radius: 0; background: var(--accent); color: var(--accent-fg) }

/* LEGO - seen from the side, the way blocks look on a shelf rather than on a
   baseplate. Each surface is a block: a solid body with a lit top edge and a
   dark seam underneath, and a row of studs poking UP off its top edge in its
   own colour.

   The studs sit on a pseudo-element placed above the element, so they occupy
   the gap that already exists between rows rather than adding any. A theme
   does not get to move things. */

body { letter-spacing: var(--track-body) }

/* ---- the block body ---- */
header, .card, .item, .stat, button.mb-btn, .mb-act, .mb-chip, #fab,
.mb-sheet, .mb-menu, .mb-toast {
  position: relative;
  border: 0;
  box-shadow:
    inset 0 3px 0 rgba(255,255,255,.34),      /* light along the top face */
    inset 0 -5px 0 rgba(0,0,0,.26),           /* the seam underneath */
    inset 3px 0 0 rgba(255,255,255,.12),
    inset -3px 0 0 rgba(0,0,0,.14);
}

/* ---- the studs, off the top edge ---- */
header::before, .card::before, .item::before, .stat::before,
button.mb-btn::before, .mb-act::before, #fab::before {
  content: ''; position: absolute; left: 6px; right: 6px; top: -7px; height: 8px;
  background-repeat: repeat-x; background-position: 0 0;
  pointer-events: none;
}
header::before { background-image: radial-gradient(ellipse 8px 7px at 12px 8px,rgba(0,0,0,.28) 0 99%,transparent 100%),radial-gradient(ellipse 7px 6px at 12px 7px,var(--surface-1) 0 99%,transparent 100%),radial-gradient(ellipse 5px 3px at 11px 5px,rgba(255,255,255,.45) 0 99%,transparent 100%); background-size: 24px 8px }
.card::before  { background-image: radial-gradient(ellipse 8px 7px at 12px 8px,rgba(0,0,0,.28) 0 99%,transparent 100%),radial-gradient(ellipse 7px 6px at 12px 7px,var(--surface-1) 0 99%,transparent 100%),radial-gradient(ellipse 5px 3px at 11px 5px,rgba(255,255,255,.45) 0 99%,transparent 100%); background-size: 24px 8px; opacity: 0 }
.item::before  { background-image: radial-gradient(ellipse 8px 7px at 12px 8px,rgba(0,0,0,.28) 0 99%,transparent 100%),radial-gradient(ellipse 7px 6px at 12px 7px,var(--surface-2) 0 99%,transparent 100%),radial-gradient(ellipse 5px 3px at 11px 5px,rgba(255,255,255,.45) 0 99%,transparent 100%); background-size: 24px 8px }
.stat::before  { background-image: radial-gradient(ellipse 8px 7px at 12px 8px,rgba(0,0,0,.28) 0 99%,transparent 100%),radial-gradient(ellipse 7px 6px at 12px 7px,var(--surface-3) 0 99%,transparent 100%),radial-gradient(ellipse 5px 3px at 11px 5px,rgba(255,255,255,.45) 0 99%,transparent 100%); background-size: 24px 8px }
button.mb-btn::before, .mb-act::before { background-image: radial-gradient(ellipse 8px 7px at 12px 8px,rgba(0,0,0,.28) 0 99%,transparent 100%),radial-gradient(ellipse 7px 6px at 12px 7px,var(--surface-3) 0 99%,transparent 100%),radial-gradient(ellipse 5px 3px at 11px 5px,rgba(255,255,255,.45) 0 99%,transparent 100%);
  background-size: 24px 8px }
#fab::before { background-image: radial-gradient(ellipse 8px 7px at 12px 8px,rgba(0,0,0,.28) 0 99%,transparent 100%),radial-gradient(ellipse 7px 6px at 12px 7px,var(--accent) 0 99%,transparent 100%),radial-gradient(ellipse 5px 3px at 11px 5px,rgba(255,255,255,.45) 0 99%,transparent 100%); background-size: 24px 8px }

/* ---- which block is which colour ---- */
/* --panel is not a token: the four base colours become --bg, --surface-1,
   --accent and --text-1. Naming the wrong one silently paints nothing. */
header { background: var(--surface-1); color: var(--text-1) }
header .logo { font-family: var(--font-display); color: var(--text-1);
  text-shadow: 0 2px 0 rgba(0,0,0,.3) }
header .logo b { color: var(--surface-3) }

/* The card is the shelf the blocks stand on: light grey, no studs of its own,
   or every block would be sitting in a field of dots. */
.card, .mb-sheet, .mb-menu, .mb-toast {
  background: #E4E6E7; color: var(--text-1);
  box-shadow: inset 0 3px 0 rgba(255,255,255,.7), inset 0 -5px 0 rgba(0,0,0,.14);
}
h2 { font-family: var(--font-display); color: #26292C }

.item { background: var(--surface-2); color: var(--text-1) }
.item .nm { color: var(--text-1); text-shadow: 0 1px 0 rgba(0,0,0,.35) }
.item.on { background: #237841 }
.item.on .nm { opacity: .72 }

.chk { border: 3px solid rgba(0,0,0,.3); background: var(--text-1); color: transparent }
.chk.on { background: var(--surface-3); border-color: rgba(0,0,0,.35); color: #1B1B1B }

.stat { background: var(--surface-3); color: #1B1B1B }
.stat b { font-family: var(--font-display); color: #1B1B1B }
.stat span { color: #4A4A4A }
.bars i { box-shadow: inset 0 3px 0 rgba(255,255,255,.3), inset 0 -4px 0 rgba(0,0,0,.22) }

button.mb-btn, .mb-act, .mb-chip, .mb-x, .mb-opt {
  font-family: var(--font-display); letter-spacing: var(--track-cap);
  background: var(--surface-3); color: #1B1B1B;
}
button.mb-btn:active, .mb-act:active {
  box-shadow: inset 0 4px 0 rgba(0,0,0,.24), inset 0 -2px 0 rgba(255,255,255,.2);
  transform: translateY(2px);
}
.mb-btn.go { background: #237841; color: var(--text-1) }
.mb-input, .mb-sel { background: var(--text-1); color: #1B1B1B; border: 0;
  box-shadow: inset 0 3px 0 rgba(0,0,0,.16) }
#fab { background: var(--accent); color: #1B1B1B }

/* MINECRAFT - built out of blocks, and readable.

   The blocks were right the first time and the reading was not: full-strength
   texture noise sat directly behind the text, and cream on an orange plank is
   not a contrast anybody wins. The textures are half as strong, the panels are
   darker, and every piece of text is white with a hard one-pixel shadow, which
   is what the game itself does and why its text stays readable over anything. */

body { image-rendering: pixelated; letter-spacing: var(--track-body) }

/* Grass over dirt. */
header {
  position: relative;
  background-color: #5A4130;
  background-image: repeating-linear-gradient(0deg,rgba(0,0,0,.09) 0 4px,rgba(255,255,255,.03) 4px 8px),repeating-linear-gradient(90deg,rgba(0,0,0,.07) 0 4px,rgba(255,255,255,.025) 4px 8px);
  background-size: 8px 8px, 8px 8px;
  border-bottom: 3px solid rgba(0,0,0,.5);
  color: var(--text-1);
}
header::before {
  content: ''; position: absolute; left: 0; right: 0; top: 0; height: 10px;
  background-color: var(--accent);
  background-image: repeating-linear-gradient(90deg,rgba(0,0,0,.14) 0 4px,rgba(255,255,255,.1) 4px 8px);
  background-size: 8px 8px;
  box-shadow: 0 3px 0 rgba(0,0,0,.22);
  pointer-events: none;
}
header .logo { font-family: var(--font-display); font-size: var(--f-2);
  color: var(--text-1); text-shadow: 2px 2px 0 #000000 }
header .logo b { color: #9BE85C }

/* Stone, darkened so white text sits on it cleanly. */
.card, .mb-sheet, .mb-menu, .mb-toast {
  background-color: var(--surface-1);
  background-image: repeating-linear-gradient(0deg,rgba(0,0,0,.07) 0 4px,rgba(255,255,255,.035) 4px 8px),repeating-linear-gradient(90deg,rgba(0,0,0,.06) 0 4px,rgba(255,255,255,.03) 4px 8px);
  background-size: 8px 8px, 8px 8px;
  border: 3px solid var(--border-strong);
  box-shadow: inset 2px 2px 0 rgba(255,255,255,.2), inset -2px -2px 0 rgba(0,0,0,.34);
  color: var(--text-1);
}
h2 { font-family: var(--font-display); font-size: var(--f-1); color: var(--text-1);
  text-shadow: 2px 2px 0 #000000 }

/* Dirt slots. */
.item, .mb-input, .mb-sel {
  background-color: var(--surface-2);
  background-image: repeating-linear-gradient(0deg,rgba(0,0,0,.09) 0 4px,rgba(255,255,255,.03) 4px 8px),repeating-linear-gradient(90deg,rgba(0,0,0,.07) 0 4px,rgba(255,255,255,.025) 4px 8px);
  background-size: 8px 8px, 8px 8px;
  border: 2px solid #241A11;
  box-shadow: inset 2px 2px 0 rgba(0,0,0,.3), inset -2px -2px 0 rgba(255,255,255,.12);
  color: var(--text-1);
}
.item .nm { color: var(--text-1); text-shadow: 1px 1px 0 #000000 }
.item.on .nm { color: #BFBFBF }

.chk { border-radius: 0; border-width: 3px; border-color: var(--border-strong);
  background: rgba(0,0,0,.25) }
.chk.on { background: var(--accent); border-color: var(--border-strong); color: var(--text-1) }

/* Planks, darkened, with white text over them. */
.stat, button.mb-btn, .mb-act, .mb-chip, .mb-x, .mb-opt, #fab {
  background-color: var(--surface-3);
  background-image: repeating-linear-gradient(0deg,rgba(0,0,0,.10) 0 6px,rgba(255,255,255,.04) 6px 12px);
  background-size: 12px 12px;
  border: 2px solid #241A11; border-radius: 0;
  color: var(--text-1);
  box-shadow: inset 2px 2px 0 rgba(255,255,255,.16), inset -2px -2px 0 rgba(0,0,0,.34);
  font-family: var(--font-display); font-size: var(--f-1); letter-spacing: 0;
  text-shadow: 1px 1px 0 #000000;
  transition: none;
}
button.mb-btn:active, .mb-act:active, #fab:active {
  box-shadow: inset 2px 2px 0 rgba(0,0,0,.34), inset -2px -2px 0 rgba(255,255,255,.14);
}
.stat b { font-family: var(--font-display); font-size: var(--f-3); color: var(--text-1);
  text-shadow: 2px 2px 0 #000000 }
.stat span { color: #E4E4E4; text-shadow: 1px 1px 0 #000000 }
#fab { background-color: var(--accent); background-image: none; font-size: var(--f-4) }
.bars i { border-radius: 0; box-shadow: inset -2px -2px 0 rgba(0,0,0,.32) }

/* MINECRAFT 2 - the inventory chrome only. the inventory screen. Light grey stone plates with a hard dark
   outline, lit on the top-left and shaded on the bottom-right, and absolutely
   nothing rounded or smoothed anywhere. */
body { image-rendering: pixelated; letter-spacing: var(--track-body) }

header {
  background: var(--surface-2);
  border-bottom: 3px solid var(--border-strong);
  box-shadow: inset 2px 2px 0 rgba(255,255,255,.55);
}
header .logo { font-family: var(--font-display); font-size: var(--f-2);
  color: var(--text-1); text-shadow: 2px 2px 0 rgba(0,0,0,.28) }
header .logo b { color: var(--accent) }

.card, .mb-sheet, .mb-menu, .mb-toast {
  background: var(--surface-1);
  border: 3px solid var(--border-strong);
  box-shadow: inset 2px 2px 0 rgba(255,255,255,.6), inset -2px -2px 0 rgba(0,0,0,.28);
}
h2 { font-family: var(--font-display); font-size: var(--f-2); color: var(--text-1);
  text-shadow: 1px 1px 0 rgba(255,255,255,.5) }

/* An inventory slot: pressed in, always. */
.item, .mb-input, .mb-sel {
  background: var(--surface-2);
  border: 2px solid var(--border);
  box-shadow: inset 2px 2px 0 rgba(0,0,0,.3), inset -2px -2px 0 rgba(255,255,255,.55);
}
.chk { border-radius: 0; border-width: 3px; border-color: var(--border-strong) }
.chk.on { background: var(--accent); border-color: var(--border-strong); color: var(--accent-fg) }

.stat { background: var(--surface-2);
  box-shadow: inset 2px 2px 0 rgba(0,0,0,.3), inset -2px -2px 0 rgba(255,255,255,.55) }
.stat b { font-family: var(--font-display); font-size: var(--f-3); color: var(--accent) }
.bars i { border-radius: 0 }

button.mb-btn, .mb-act, .mb-chip, .mb-x, .mb-opt, #fab {
  font-family: var(--font-display); font-size: var(--f-2); letter-spacing: 0;
  background: var(--surface-3); color: var(--text-1);
  border: 2px solid var(--border-strong); border-radius: 0;
  box-shadow: inset 2px 2px 0 rgba(255,255,255,.6), inset -2px -2px 0 rgba(0,0,0,.28);
  transition: none;
}
button.mb-btn:active, .mb-act:active, #fab:active {
  box-shadow: inset 2px 2px 0 rgba(0,0,0,.3), inset -2px -2px 0 rgba(255,255,255,.5);
}
#fab { background: var(--accent); color: var(--accent-fg); font-size: var(--f-4) }

/* DRAGON QUEST - the command window. Solid navy, a thick white frame with a
   second line inside it, white text, square corners, and nothing else at all.
   The restraint is the look. */
body { letter-spacing: var(--track-body) }

header {
  background: var(--surface-1);
  border-bottom: 4px solid var(--text-1);
  box-shadow: inset 0 0 0 2px var(--surface-1), inset 0 -8px 0 -6px var(--text-1);
}
header .logo { font-family: var(--font-display); color: var(--text-1) }
header .logo b { color: var(--accent) }

/* The signature: white frame, gap, white frame. */
.card, .mb-sheet, .mb-menu, .mb-toast {
  background: var(--surface-1);
  border: 4px solid var(--text-1);
  box-shadow: inset 0 0 0 2px var(--surface-1), inset 0 0 0 4px var(--text-1);
}
h2 { font-family: var(--font-display); color: var(--accent);
  border-bottom: 2px solid var(--border); padding-bottom: var(--s-2) }

.item { background: transparent; border: 0 }
/* Selection is the pointing arrow, the way a command list works. */
.item.on .nm { color: var(--text-2) }
.item::before { content: ''; width: 0; height: 0; flex: 0 0 auto; margin-right: -6px;
  border-left: 7px solid transparent; border-top: 5px solid transparent;
  border-bottom: 5px solid transparent }
.item.on::before { border-left-color: var(--accent) }

.chk { border-radius: 0; border-width: 2px; border-color: var(--text-1) }
.chk.on { background: var(--accent); border-color: var(--text-1); color: var(--accent-fg) }

.stat { background: transparent; border: 2px solid var(--text-1) }
.stat b { font-family: var(--font-display); color: var(--accent) }

button.mb-btn, .mb-act, .mb-chip, .mb-x, .mb-opt, #fab {
  font-family: var(--font-display); letter-spacing: var(--track-cap);
  background: var(--surface-1); color: var(--text-1);
  border: 2px solid var(--text-1); border-radius: 0;
}
button.mb-btn:active, .mb-act:active { background: var(--text-1); color: var(--surface-1) }
.mb-btn.go { background: var(--accent); color: var(--accent-fg); border-color: var(--text-1) }
.mb-input, .mb-sel { background: var(--surface-2); border: 2px solid var(--text-1);
  border-radius: 0; color: var(--text-1) }
#fab { background: var(--surface-1); color: var(--accent); border-radius: 0; border-width: 4px }

/* FFVII - the PlayStation menu. Every panel is a translucent blue box graded
   from near-black at the bottom to a lit blue at the top, edged with a thin
   pale line, with white text that carries a hard shadow. */
body { letter-spacing: var(--track-body) }

header {
  background: linear-gradient(180deg, var(--surface-3), var(--surface-1));
  border-bottom: var(--border-width) solid var(--border-strong);
}
header .logo { font-family: var(--font-display); color: var(--text-1);
  text-shadow: 2px 2px 0 rgba(0,0,0,.7) }
header .logo b { color: var(--accent) }

.card, .mb-sheet, .mb-menu, .mb-toast {
  background: linear-gradient(180deg, var(--surface-3), var(--surface-1));
  border: var(--border-width) solid var(--border-strong);
  box-shadow: inset 0 0 0 1px rgba(0,0,0,.5);
}
h2 { font-family: var(--font-display); color: var(--text-1);
  text-shadow: 2px 2px 0 rgba(0,0,0,.6);
  border-bottom: var(--border-width) solid var(--border); padding-bottom: var(--s-2) }

.item { background: transparent; border: 0 }
.item .nm { text-shadow: 1px 1px 0 rgba(0,0,0,.6) }
.item.on .nm { color: var(--accent) }
/* the hand cursor, as a triangle on the live row */
.item::before { content: ''; width: 0; height: 0; flex: 0 0 auto; margin-right: -4px;
  border-left: 8px solid transparent; border-top: 5px solid transparent;
  border-bottom: 5px solid transparent }
.item.on::before { border-left-color: var(--accent) }

.chk { border-color: var(--border-strong) }
.chk.on { background: var(--accent); border-color: var(--accent); color: var(--accent-fg) }

.stat { background: linear-gradient(180deg, var(--surface-3), var(--surface-1));
  border: var(--border-width) solid var(--border) }
.stat b { font-family: var(--font-display); color: var(--text-1);
  text-shadow: 2px 2px 0 rgba(0,0,0,.6) }

button.mb-btn, .mb-act, .mb-chip, .mb-x, .mb-opt {
  font-family: var(--font-display); letter-spacing: var(--track-cap);
  background: linear-gradient(180deg, var(--surface-3), var(--surface-1));
  color: var(--text-1); border: var(--border-width) solid var(--border-strong);
  text-shadow: 1px 1px 0 rgba(0,0,0,.6);
}
button.mb-btn:active, .mb-act:active { color: var(--accent) }
.mb-btn.go { border-color: var(--accent); color: var(--accent) }
.mb-input, .mb-sel { background: rgba(0,0,0,.35);
  border: var(--border-width) solid var(--border-strong); color: var(--text-1) }
#fab { background: linear-gradient(180deg, var(--surface-3), var(--surface-1));
  color: var(--accent); border: 2px solid var(--border-strong) }
